/* ---------- entrenador inteligente: rutina por reglas (objetivo, nivel, días, lesiones, equipos operativos, mediciones) ---------- */
const GRT_TPL={2:[['Día A · Cuerpo completo',['legs','push','pull','hinge','core','arms']],['Día B · Cuerpo completo',['hinge','pull','push','legs','core','shoulders']]],
 3:[['Día A · Piernas y empuje',['legs','push','legs','shoulders','core','arms']],['Día B · Espalda y glúteos',['hinge','pull','pull','hinge','core','arms']],['Día C · Cuerpo completo',['legs','push','pull','hinge','core','shoulders']]],
 4:[['Día A · Tren inferior',['legs','hinge','legs','hinge','core','legs']],['Día B · Tren superior',['push','pull','shoulders','pull','arms','push']],['Día C · Tren inferior',['hinge','legs','hinge','legs','core','core']],['Día D · Tren superior',['pull','push','pull','shoulders','arms','arms']]],
 5:[['Día A · Empuje',['push','push','shoulders','shoulders','arms','core']],['Día B · Tracción',['pull','pull','shoulders','arms','core','pull']],['Día C · Piernas',['legs','hinge','legs','hinge','legs','core']],['Día D · Tren superior',['push','pull','shoulders','arms','push','pull']],['Día E · Tren inferior y cardio',['hinge','legs','core','cardio','hinge','legs']]]};
const GRT_PRM={fuerza:{s:[3,4,5],r:'4-6',rest:150},hipertrofia:{s:[3,3,4],r:'8-12',rest:90},grasa:{s:[2,3,3],r:'12-15',rest:45},salud:{s:[2,3,3],r:'10-12',rest:60},rendimiento:{s:[3,4,4],r:'6-8',rest:120}};
function gymGenRoutine(o,EX,MQ){
 const lv=Math.max(0,['principiante','intermedio','avanzado'].indexOf(o.level)),inj=o.inj||[],P=GRT_PRM[o.goal]||GRT_PRM.salud,n=[4,5,6][lv];
 const days=GRT_TPL[Math.min(5,Math.max(2,+o.days||3))];
 const avail=e=>{if(!e.mach.length)return true;if(o.home)return e.mach.some(id=>id==='eq3');return e.mach.some(id=>{const q=MQ.find(x=>x.id===id);return q&&q.state==='ok';});};
 let pool=EX.filter(e=>avail(e)&&!e.avoid.some(a=>inj.includes(a)));
 if(lv===0)pool=pool.filter(e=>e.mach.length).concat(pool.filter(e=>!e.mach.length));
 const rot={},sh=o.shift||0;
 const out=days.map(d=>{const used={},items=[];
  d[1].slice(0,n).forEach(cat=>{const L=pool.filter(e=>e.cat===cat&&!used[e.id]);if(!L.length)return;const k=((rot[cat]||0)+sh)%L.length;rot[cat]=(rot[cat]||0)+1;const e=L[k];used[e.id]=1;const cr=cat==='core';
   items.push({ex:e.id,s:cr?Math.max(2,P.s[lv]-1):P.s[lv],r:cr?(/Plancha/.test(e.name)?'30-45 s':'10-12'):P.r,kg:'',rest:cr?45:P.rest});});
  if(o.goal==='grasa'){const c=pool.filter(e=>e.cat==='cardio');if(c.length){rot.cardio=(rot.cardio||0)+1;const e=c[(rot.cardio+sh)%c.length];items.push({ex:e.id,s:1,r:'12 min',kg:'',rest:0});}}
  return{n:d[0],items};});
 const notes=[];
 if(inj.length)notes.push('Se dejaron afuera '+EX.filter(e=>e.avoid.some(a=>inj.includes(a))).length+' ejercicios por cuidado de '+inj.map(i=>GINJ[i].toLowerCase()).join(' y ')+'.');
 const rep=MQ.filter(q=>q.state!=='ok');if(rep.length&&!o.home)notes.push('No se usan equipos en reparación: '+rep.map(q=>q.name).join(', ')+'.');
 if(o.home)notes.push('Modalidad virtual: sólo ejercicios con peso corporal o bandas elásticas.');
 if(lv===0)notes.push('Nivel principiante: se priorizan ejercicios guiados y menos ejercicios por día.');
 if(o.trend)notes.push(o.trend);
 notes.push('Progresión: cuando completes todas las series con buena técnica, subí entre 2,5 y 5 % la carga.');
 return{name:(GGOALS[o.goal]||'Rutina')+' · '+days.length+' días',goal:o.goal,level:o.level,days:out,notes};}

/* ---------- estado ---------- */
function gymCfgDef(){return{grace:3,alertDays:5,capacity:isNC()?12:60,mpLink:'',alias:'',appUrl:''};}
function gymInit(){if(!S.gym)S.gym={};const G=S.gym;G.cfg=Object.assign(gymCfgDef(),G.cfg||{});
 ['plans','classes','res','catt','att','acc','slots','routines','mq','ex'].forEach(k=>{if(!Array.isArray(G[k]))G[k]=[];});if(!G.m||typeof G.m!=='object')G.m={};return G;}
const G=()=>S.gym||gymInit();
const gm=cid=>G().m[cid]||null;
const gPlan=id=>G().plans.find(p=>p.id===id)||null;
const gPlanOf=m=>(m&&gPlan(m.plan))||null;
const gPrice=pl=>{const p=pl&&prod(pl.pid);return p?p.price:0;};
const gCust=cid=>custById(cid);
const gName=c=>c?custFull(c):'—';
const gCode=c=>(isNC()?'MI-':'SG-')+String(c.num||0).padStart(5,'0');
const gEx=id=>G().ex.find(e=>e.id===id);
const gMq=id=>G().mq.find(q=>q.id===id);
const gNext=q=>addDays(q.last,q.every);
const gFrozen=m=>!!(m&&m.freeze&&m.freeze.from<=gT()&&m.freeze.until>=gT());
const gActive=c=>c&&c.status!=='baja'&&gm(c.id)&&!gm(c.id).baja;
const gMembers=()=>S.customers.filter(c=>!c.elim&&gm(c.id));
const gActives=()=>gMembers().filter(gActive);
function gStatus(c){const m=gm(c.id),t=gT(),g=+G().cfg.grace||0;if(!m)return{k:'',t:'Sin '+GW().m};
 if(c.status==='baja'||m.baja)return{k:'mute',t:'Baja'};if(gFrozen(m))return{k:'mute',t:(isNC()?'Congelado':'Congelada')+' hasta '+dmy(m.freeze.until)};
 if(m.nuevo&&m.due<t)return{k:'warn',t:'Pendiente de primer pago'};
 if(m.due<t){const d=gDiff(m.due,t);return d<=g?{k:'warn',t:'En gracia · vencida hace '+d+' d'}:{k:'bad',t:'Vencida hace '+d+' d'};}
 const left=gDiff(t,m.due);if(left<=(+G().cfg.alertDays||5))return{k:'warn',t:left===0?'Vence hoy':'Vence en '+left+' d'};return{k:'ok',t:'Al día'};}
const gTag=s=>`<span class="tag ${s.k==='mute'?'':s.k}">${esc(s.t)}</span>`;
const gAttOf=cid=>G().att.filter(a=>a.cust===cid);
const gLastAtt=cid=>{const L=gAttOf(cid).map(a=>a.date).sort();return L[L.length-1]||'';};
const gAttToday=cid=>G().att.some(a=>a.cust===cid&&a.date===gT());
const gWeekCount=cid=>{const w=gWeekStart(gT());return gAttOf(cid).filter(a=>a.date>=w).length;};
const gMonthAtt=cid=>{const ms=gT().slice(0,8)+'01';return gAttOf(cid).filter(a=>a.date>=ms).length;};
function gStreak(cid){let ws=gWeekStart(gT()),n=0;const D=gAttOf(cid).map(a=>a.date);const cnt=w=>D.filter(d=>d>=w&&d<=addDays(w,6)).length;if(cnt(ws)<2)ws=addDays(ws,-7);while(cnt(ws)>=2&&n<60){n++;ws=addDays(ws,-7);}return n;}
const gRoutineOf=cid=>G().routines.filter(r=>r.cust===cid).sort((a,b)=>b.created.localeCompare(a.created))[0];
function gTrend(m){const L=(m.measures||[]).slice().sort((a,b)=>a.date.localeCompare(b.date));if(L.length<2)return'';
 const ch=k=>{const H=L.filter(x=>x[k]!=null&&x[k]!=='');return H.length>=2?+(H[H.length-1][k]-H[0][k]).toFixed(1):null;};const dp=ch('peso'),dg=ch('grasa'),sg=v=>(v>0?'+':'')+String(v).replace('.',',');
 if(dp==null&&dg==null)return'';return'Mediciones desde el '+dmy(L[0].date)+':'+(dp!=null?' peso '+sg(dp)+' kg':'')+(dp!=null&&dg!=null?',':'')+(dg!=null?' grasa '+sg(dg)+' puntos':'')+'.'+(m.goal==='grasa'&&dp!=null&&dp>=0?' El peso no baja: se suma cardio al final de cada día.':'');}
