 if(kind==='venc')return`Hola ${f}, te recordamos que tu ${GW().m} ${pl?pl.name:''} en ${biz} vence el ${dmy(m.due)}.${pay} ¡Te esperamos!`;
 if(kind==='vencida')return`Hola ${f}, tu ${GW().m} ${pl?pl.name:''} en ${biz} venció el ${dmy(m.due)}. Podés renovarla en recepción o por transferencia.${pay}`;
 if(kind==='riesgo')return`Hola ${f}, hace unos días que no te vemos en ${biz}. ¿Te esperamos esta semana?`;
