/* ---------- membresía: cobro en Vender (la venta extiende el vencimiento) ---------- */
function gymApplySale(sale){if(!sale||!sale.cust)return;const c=gCust(sale.cust);if(!c)return;
 sale.items.forEach(it=>{const p=prod(it.pid);if(!p||!p.gymPlan)return;const pl=gPlan(p.gymPlan);if(!pl)return;const G0=G();const t=gT(),g=+G0.cfg.grace||0;
  let m=G0.m[c.id];if(!m){m=G0.m[c.id]={plan:pl.id,due:addDays(t,-1),nuevo:true,goal:'salud',level:'principiante',inj:[],health:'',decl:false,nfc:'',trainer:'',mode:pl.mode||'presencial',measures:[],created:t,freeze:null};}
  const prev=m.due,base=(m.due>=t||(!m.nuevo&&gDiff(m.due,t)<=g))?m.due:t;let until=base;const q=Math.max(1,Math.round(it.qty));
  for(let i=0;i<q;i++)until=pl.days?addDays(until,pl.days):gAddM(until,1);
  m.plan=pl.id;m.due=until;m.nuevo=false;m.baja=false;if(c.status==='baja')c.status='activo';
  (G0.pays=G0.pays||[]).push({id:uid(),sale:sale.id,saleN:sale.n,cust:c.id,plan:pl.id,prev,until,amt:Math.round(it.qty*it.price)-(it.disc||0),ts:sale.ts});
  audit('GYM_CUOTA',gName(c)+' · '+pl.name+' · venta '+sale.n+' · '+dmy(prev)+' → '+dmy(until),{ent:'gym',eid:c.id,old:prev,nw:until});
  gLastPay={cust:c.id,until,plan:pl.name,n:sale.n};});}
let gLastPay=null;
if(typeof commitSale==='function'){const _gymCommit=commitSale;commitSale=function(method,arca,channel,lines,opts){
 if(isGymBuild()){const L=lines||pos.lines;if(L.some(l=>{const p=prod(l.pid);return p&&p.gymPlan;})&&!(opts&&opts.custId))return{err:'La cuota '+(isNC()?'del plan necesita un alumno':'de la membresía necesita un socio')+': elegí el cliente antes de cobrar.'};}
 const r=_gymCommit.apply(this,arguments);if(r&&r.sale&&isGymBuild()){try{gymApplySale(r.sale);save();}catch(e){}}return r;};}
A.gPay=el=>{const c=gCust(el.dataset.id);if(!c)return;$$('#modal-root .ov').forEach(o=>o.remove());const m=gm(c.id),pl=gPlanOf(m)||G().plans[0];if(!pl)return toast(isNC()?'Primero creá un plan.':'Primero creá una membresía.',1);const p=prod(pl.pid);if(!p||!p.active)return toast('El artículo de '+(isNC()?'este plan':'esta membresía')+' no está activo en Inventario.',1);
 if(pos.lines.length&&!pos.lines.every(l=>{const q=prod(l.pid);return q&&q.gymPlan;}))return toast('Terminá o borrá la operación que está en Vender antes de cobrar una cuota.',1);
 if(gFrozen(m))toast((isNC()?'Ojo: el plan está congelado':'Ojo: la membresía está congelada')+'. Al cobrar se renueva desde el vencimiento corrido.');
 pos.lines=[{pid:p.id,name:pfull(p),rubro:p.rubro,qty:1,price:p.price,cost:p.cost,unit:p.unit,list:p.price}];pos.sel=0;pos.cust=c.id;pos.chanSet=null;
 audit('GYM_COBRO_A_VENDER',gName(c)+' · '+pl.name);toast('Cuota de '+gName(c)+' cargada en Vender: elegí el medio de pago y cobrá.'+(typeof openSess==='function'&&!openSess()?' Antes abrí la caja.':''));go('vender');};

/* ---------- acceso: QR, NFC (lector USB) o documento ---------- */
let gAcc={meth:'auto',res:null,t:0};
function gResolve(meth,v){v=String(v||'').trim();if(!v)return null;const u=v.toUpperCase(),dg=v.replace(/\D/g,'');
 const F={qr:c=>gCode(c)===u||gCode(c).replace('-','')===u,nfc:c=>{const m=gm(c.id);return !!(m&&m.nfc&&m.nfc.toUpperCase()===u);},dni:c=>!!dg&&c.dni===dg};
 const order=meth==='auto'?['qr','nfc','dni']:[meth];const L=gMembers();
 for(const k of order){const c=L.find(F[k]);if(c)return{c,meth:k};}return null;}
function gInside(){const t=gT(),lim=now()-3*36e5,last={};G().acc.filter(a=>a.res!=='denied'&&a.ts>=lim&&dkey(a.ts)===t).sort((a,b)=>a.ts-b.ts).forEach(a=>{last[a.cust]=a;});
 return Object.values(last).filter(a=>a.type!=='out').map(a=>({c:gCust(a.cust),ts:a.ts})).filter(x=>x.c).sort((a,b)=>b.ts-a.ts);}
function gProcess(c,meth){const m=gm(c.id),t=gT(),pl=gPlanOf(m),g=+G().cfg.grace||0;const warns=[],notes=[];let res='ok',why='';
 if(!m||c.status==='baja'||m.baja){res='denied';why='Dado de baja';}
 else if(gFrozen(m)){res='denied';why=(isNC()?'Plan congelado':'Membresía congelada')+' hasta el '+dmy(m.freeze.until)+(m.freeze.reason?' ('+m.freeze.reason+')':'');}
 else if(m.nuevo&&m.due<t){res='denied';why='Pendiente de primer pago';}
 else if(m.due<t){const d=gDiff(m.due,t);if(d<=g)warns.push('Período de gracia: venció hace '+d+(d===1?' día':' días')+', le '+(g-d===1?'queda 1 día':'quedan '+(g-d)+' días'));else{res='denied';why='Cuota vencida desde el '+dmy(m.due);}}
 if(res!=='denied'){const left=gDiff(t,m.due);if(left>=0&&left<=(+G().cfg.alertDays||5))warns.push(left===0?'Su cuota vence hoy':'Su cuota vence el '+dmy(m.due));
  if(pl&&pl.weekly&&!gAttToday(c.id)&&gWeekCount(c.id)>=pl.weekly)warns.push('Ya completó sus '+pl.weekly+' sesiones de la semana');
  if(!m.decl)warns.push('Falta la declaración de salud');
  const debt=typeof debtOf==='function'?debtOf(c.id):0;if(debt>0)warns.push('Saldo en cuenta corriente: '+money(debt));
  const cap=+G().cfg.capacity||0;if(cap&&gInside().length>=cap)warns.push('Aforo completo: '+cap+' personas adentro');
  if(warns.length)res='warn';}
 if(c.birth&&c.birth.slice(5)===t.slice(5))notes.push('Hoy es su cumpleaños');
 if(res!=='denied'&&gAttToday(c.id))notes.push('Ya había ingresado hoy');
 const k=gStreak(c.id);if(res!=='denied'&&k>=3)notes.push('Racha de '+k+' semanas seguidas entrenando');
 if(res!=='denied'&&!gAttToday(c.id))G().att.push({id:uid(),cust:c.id,date:t,ts:now(),method:meth});
 G().acc.push({id:uid(),cust:c.id,ts:now(),method:meth,res,why:why||warns.join(' · '),type:'in'});
 if(meth==='manual'||res==='denied')audit(res==='denied'?'GYM_ACCESO_DENEGADO':'GYM_INGRESO_MANUAL',gName(c)+(why?' · '+why:''));
 save();return{cust:c.id,res,why,warns,notes,meth,at:now()};}
function gGate(r,full){if(!r)return`<div class="g-idle"><b>Esperando lectura</b><span>Mostrá el QR de la app, acercá la tarjeta NFC al lector o ingresá el documento.</span></div>`;
 if(r.nf)return`<div class="g-gate mute"><div class="g-gt">NO RECONOCIDO</div><div class="g-gn">Sin coincidencias</div><p>No hay ningún ${GW().s} con «${esc(r.q)}». Probá con otro método o buscá por nombre en ${GW().SS}.</p></div>`;
 const c=gCust(r.cust);if(!c)return'';const m=gm(c.id),pl=gPlanOf(m);const cls=r.res==='denied'?'bad':r.res;
 const lines=(r.res==='denied'?[r.why]:r.warns).concat(r.notes);
 return`<div class="g-gate ${cls}"><div class="g-gt">${r.res==='ok'?'ACCESO AUTORIZADO':r.res==='warn'?'ACCESO CON AVISO':'ACCESO DENEGADO'}</div><div class="g-gn">${esc(gName(c))}</div><div class="sm">${esc(pl?pl.name:'')} · ${GMETH[r.meth]||r.meth} · ${hm(r.at)}${pl&&pl.weekly?' · semana '+gWeekCount(c.id)+' de '+pl.weekly:''}</div>${lines.length?'<ul>'+lines.map(l=>`<li>${esc(l)}</li>`).join('')+'</ul>':''}</div>`+
 (full?`<div class="row" style="margin-top:.6rem">${r.res==='denied'&&!gFrozen(m)&&c.status!=='baja'?`<button class="btn gold" data-act="gPay" data-id="${c.id}">Cobrar cuota</button>`:''}<button class="btn" data-act="gFicha" data-id="${c.id}">Ver ficha</button></div>`:'');}
function gFeed(n){const L=G().acc.slice().sort((a,b)=>b.ts-a.ts).slice(0,n);if(!L.length)return'<p class="mut sm">Sin movimientos.</p>';
 return`<div class="tw"><table><thead><tr><th>Hora</th><th>${GW().S}</th><th>Método</th><th>Resultado</th></tr></thead><tbody>${L.map(a=>{const c=gCust(a.cust);return`<tr><td>${dmy(dkey(a.ts)).slice(0,-3)} ${hm(a.ts)}</td><td>${esc(gName(c))}${a.why?`<div class="sm mut">${esc(a.why)}</div>`:''}</td><td>${GMETH[a.method]||a.method}</td><td>${a.type==='out'?'<span class="tag">Salida</span>':`<span class="tag ${a.res==='ok'?'ok':a.res==='warn'?'warn':'bad'}">${a.res==='ok'?'Autorizado':a.res==='warn'?'Con aviso':'Denegado'}</span>`}</td></tr>`;}).join('')}</tbody></table></div>`;}
function gInsideHTML(){const L=gInside(),cap=+G().cfg.capacity||0;
 return`<div class="row"><h3 class="sp">Adentro ahora</h3><span class="tag">${L.length}${cap?' de '+cap:''}</span></div>${cap?`<div class="g-meter${L.length>=cap?' full':''}"><i style="width:${Math.min(100,Math.round(L.length/cap*100))}%"></i></div>`:''}
 ${L.length?`<div class="tw"><table><tbody>${L.slice(0,12).map(x=>`<tr><td>${esc(gName(x.c))}<div class="sm mut">entró ${hm(x.ts)}</div></td><td class="r"><button class="btn sm" data-act="gExit" data-id="${x.c.id}">Salida</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="mut sm">No hay nadie adentro.</p>'}<p class="sm mut">Si alguien no marca la salida, se lo da por salido a las 3 horas.</p>`;}
function gAccRefresh(){const set=(s,h)=>{const e=$(s);if(e)e.innerHTML=h;};set('#g-res',gGate(gAcc.res,true));set('#g-kres',gGate(gAcc.res,false));set('#g-feed',gFeed(10));set('#g-in',gInsideHTML());const i=$('#g-q')||$('#g-kq');if(i){i.value='';i.focus();}}
function gShow(r){gAcc.res=r;gAccRefresh();clearTimeout(gAcc.t);gAcc.t=setTimeout(()=>{gAcc.res=null;gAccRefresh();},8000);}
function gRead(v){const r=gResolve(gAcc.meth,v);if(r)gShow(gProcess(r.c,r.meth));else gShow({nf:true,q:v});}
A.gMeth=el=>{gAcc.meth=el.dataset.m;rerender();};
A.gExit=el=>{const c=gCust(el.dataset.id);if(!c)return;G().acc.push({id:uid(),cust:c.id,ts:now(),method:'salida',res:'ok',why:'',type:'out'});save();gAccRefresh();toast('Salida registrada: '+gName(c));};
A.gSim=el=>{const k=el.dataset.k,t=gT(),g=+G().cfg.grace||0,al=+G().cfg.alertDays||5;const A0=gActives().filter(c=>!gFrozen(gm(c.id))&&!gm(c.id).nuevo);
 const pools={ok:A0.filter(c=>gDiff(t,gm(c.id).due)>al),warn:A0.filter(c=>{const d=gDiff(t,gm(c.id).due);return d>=0&&d<=al;}),grace:A0.filter(c=>{const d=gDiff(gm(c.id).due,t);return d>0&&d<=g;}),bad:A0.filter(c=>gDiff(gm(c.id).due,t)>g),frozen:gActives().filter(c=>gFrozen(gm(c.id)))};
 const L=pools[k]||[];if(!L.length)return toast('No hay '+GW().ss+' en esa situación.',1);const c=L[Math.floor(Math.random()*L.length)];const meth=gAcc.meth==='auto'?(Math.random()<.5?'qr':'dni'):gAcc.meth;
 gRead(meth==='dni'?c.dni:meth==='nfc'?(gm(c.id).nfc||gCode(c)):gCode(c));};
A.gKiosk=()=>{const k=document.createElement('div');k.id='g-kiosk';k.className='g-kiosk';k.setAttribute('role','dialog');k.setAttribute('aria-label','Tótem de acceso');
 k.innerHTML=`<div class="g-kin"><div class="row"><img src="${LOGO_MENU}" alt="" style="height:52px;border-radius:8px"><b class="sp" style="font:700 1.6rem Georgia,serif">${esc(S.tenant.name)}</b><span class="g-clock" id="g-clock">${hm(now())}</span></div>
 <label for="g-kq" style="font-size:1.1rem">Pasá tu QR o tu tarjeta, o ingresá tu documento</label><div class="row"><input id="g-kq" autocomplete="off" style="min-height:64px;font-size:1.4rem;flex:1"><button class="btn gold" data-act="gKgo" style="min-height:64px">Entrar</button></div>
 <div id="g-kres">${gGate(null)}</div><div class="row"><button class="btn sm" data-act="gSim" data-k="ok">Simular al día (demostración)</button><button class="btn sm" data-act="gSim" data-k="bad">Simular vencida (demostración)</button><span class="sp"></span><button class="btn sm" data-act="gKclose">Salir del tótem</button></div>${vbFooter(true)}</div>`;
 document.body.appendChild(k);const i=$('#g-kq');i.focus();i.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();A.gKgo();}});
 gAcc.ck=setInterval(()=>{const c=$('#g-clock');if(c)c.textContent=hm(now());else clearInterval(gAcc.ck);},15000);};
