/* ---------- socios / alumnos ---------- */
let gF={q:'',f:'activos',plan:'',pg:0};
function gFilter(){const t=gT(),g=+G().cfg.grace||0,sg=gSegments();let L=gMembers();const q=gF.q.trim().toLowerCase();
 if(q)L=L.filter(c=>gName(c).toLowerCase().includes(q)||(c.dni||'').includes(q)||(c.wa||'').includes(q)||gCode(c).toLowerCase().includes(q));
 if(gF.plan)L=L.filter(c=>gm(c.id).plan===gF.plan);
 const f=gF.f,ids=a=>new Set(a.map(c=>c.id));
 if(f==='activos')L=L.filter(gActive);else if(f==='aldia')L=L.filter(c=>gActive(c)&&gm(c.id).due>=t);else if(f==='porvencer'){const s=ids(sg.venc);L=L.filter(c=>s.has(c.id));}
 else if(f==='gracia')L=L.filter(c=>gActive(c)&&!gm(c.id).nuevo&&gm(c.id).due<t&&gDiff(gm(c.id).due,t)<=g);else if(f==='vencidas'){const s=ids(sg.vencida);L=L.filter(c=>s.has(c.id));}
 else if(f==='congeladas'){const s=ids(sg.congel);L=L.filter(c=>s.has(c.id));}else if(f==='riesgo'){const s=ids(sg.riesgo);L=L.filter(c=>s.has(c.id));}
 else if(f==='sinrutina')L=L.filter(c=>gActive(c)&&!gRoutineOf(c.id));else if(f==='sindecl')L=L.filter(c=>gActive(c)&&!gm(c.id).decl);else if(f==='baja')L=L.filter(c=>!gActive(c));
 return L.sort((a,b)=>gName(a).localeCompare(gName(b),'es'));}
function gKpis(){const t=gT(),A=gActives(),okN=A.filter(c=>gm(c.id).due>=t).length,sg=gSegments(),ms=t.slice(0,8)+'01';
 const due7=A.filter(c=>{const m=gm(c.id);return !gFrozen(m)&&m.due>=t&&m.due<=addDays(t,7);}),due7s=due7.reduce((a,c)=>a+gPrice(gPlanOf(gm(c.id))),0);
 const cuotas=(G().pays||[]).filter(p=>dkey(p.ts)>=ms).reduce((a,p)=>a+p.amt,0);const mrr=A.reduce((a,c)=>a+gPrice(gPlanOf(gm(c.id))),0);
 const K=(l,v,f,act)=>`<div class="card kpi"${act?` data-act="gGoF" data-f="${act}" role="button" tabindex="0" style="cursor:pointer"`:''}><span>${l}</span><b>${v}</b><span>${f}</span></div>`;
 return`<div class="grid g4">${K(GW().SS+' activos',A.length,gMembers().filter(c=>gm(c.id).created>=ms).length+' altas este mes · '+sg.congel.length+(isNC()?' congelado(s)':' congelada(s)'),'activos')}${K('Cuotas al día',okN+' de '+A.length,(A.length?Math.round((A.length-okN)/A.length*100):0)+' % de mora ('+(A.length-okN)+' ÷ '+A.length+')','vencidas')}${K('A cobrar en 7 días',money(due7s),due7.length+' cuota(s) vencen hasta el '+dmy(addDays(t,7)),'porvencer')}${K('Cuotas cobradas en el mes',money(cuotas),'Ingreso mensual esperado '+money(mrr),'')}${K('Riesgo de abandono',sg.riesgo.length,'Al día pero sin venir hace 14 días o más','riesgo')}${K('Rutinas asignadas',new Set(G().routines.map(r=>r.cust)).size,'de '+A.length+' '+GW().ss+' activos','sinrutina')}${isNC()?'':K('Adentro ahora',gInside().length+(G().cfg.capacity?' de '+G().cfg.capacity:''),'según accesos de las últimas 3 horas','')}${K('Asistencias hoy',G().att.filter(a=>a.date===t).length,'una por persona y día','')}</div>`;}
A.gGoF=el=>{gF.f=el.dataset.f;gF.pg=0;go('gsocios');rerender();};
reg('gsocios',isNC()?'Alumnos':'Socios','users','gym',()=>{const L=gFilter(),pg=40,pages=Math.max(1,Math.ceil(L.length/pg));if(gF.pg>=pages)gF.pg=pages-1;const P=L.slice(gF.pg*pg,gF.pg*pg+pg);
 const FL=[['activos','Activos'],['aldia','Al día'],['porvencer','Por vencer'],['gracia','En período de gracia'],['vencidas','Vencidas'],['congeladas','Congeladas'],['riesgo','En riesgo de abandono'],['sinrutina','Sin rutina'],['sindecl','Sin declaración de salud'],['baja','Bajas'],['todos','Todos']];
 return`<div class="row"><h1 class="sp">${GW().SS}</h1>${expBarG()}<button class="btn gold" data-act="gNew">+ ${GW().S}</button></div>${gKpis()}
 <div class="card" style="margin-top:1rem"><div class="row"><div class="sp"><label for="gs-q">Buscar por nombre, documento, WhatsApp o código</label><input id="gs-q" value="${esc(gF.q)}" autocomplete="off" placeholder="Ej: Lucía, 33123456"></div>
 <div><label for="gs-f">Mostrar</label><select id="gs-f">${FL.map(([k,l])=>`<option value="${k}" ${gF.f===k?'selected':''}>${l}</option>`).join('')}</select></div><div><label for="gs-p">${GW().M}</label><select id="gs-p"><option value="">${isNC()?'Todos':'Todas'}</option>${G().plans.map(p=>`<option value="${p.id}" ${gF.plan===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div></div>
 <p class="sm mut">${L.length} resultado(s)</p><div class="tw"><table><thead><tr><th>${GW().S}</th><th>${GW().M}</th><th>Paga hasta</th><th>Estado</th><th class="r">Acciones</th></tr></thead><tbody>${P.map(c=>{const m=gm(c.id),pl=gPlanOf(m),st=gStatus(c);
  return`<tr><td><b>${esc(gName(c))}</b>${c.origin==='ejemplo'?' <span class="tag sim">ejemplo</span>':''}<div class="sm mut">${gCode(c)} · DNI ${esc(c.dni||'—')}${m.mode==='virtual'?' · virtual':''}</div></td><td>${esc(pl?pl.name:'—')}</td><td>${dmy(m.due)}</td><td>${gTag(st)}${m.decl?'':' <span class="tag warn">sin declaración</span>'}</td>
  <td class="r"><button class="btn sm" data-act="gFicha" data-id="${c.id}">Ficha</button>${st.k==='ok'||st.k==='mute'?'':`<button class="btn sm gold" data-act="gPay" data-id="${c.id}">Cobrar</button>`}${st.k==='bad'?gWaBtn(c,'vencida','WhatsApp'):st.k==='warn'?gWaBtn(c,'venc','WhatsApp'):''}</td></tr>`;}).join('')||`<tr><td colspan="5" class="mut">No hay ${GW().ss} con este filtro.</td></tr>`}</tbody></table></div>
 ${pages>1?`<div class="row"><button class="btn sm" data-act="gPg" data-d="-1" ${gF.pg?'':'disabled'}>Anterior</button><span class="sp sm mut" style="text-align:center">Página ${gF.pg+1} de ${pages}</span><button class="btn sm" data-act="gPg" data-d="1" ${gF.pg<pages-1?'':'disabled'}>Siguiente</button></div>`:''}</div>
 ${gCampaignCard()}`;},()=>{const q=$('#gs-q');if(q){q.addEventListener('input',()=>{gF.q=q.value;gF.pg=0;clearTimeout(gF.t);gF.t=setTimeout(()=>{rerender();setTimeout(()=>{const n=$('#gs-q');if(n){n.focus();n.setSelectionRange(n.value.length,n.value.length);}},0);},250);});}
 ['gs-f','gs-p'].forEach(id=>{const e=$('#'+id);e&&e.addEventListener('change',()=>{gF.f=val('gs-f');gF.plan=val('gs-p');gF.pg=0;rerender();});});},'Gimnasio');
A.gPg=el=>{gF.pg=Math.max(0,gF.pg+(+el.dataset.d));rerender();};
function expBarG(){return can('impex')?`<button class="btn sm" data-act="gCsv">Exportar CSV</button>`:'';}
A.gCsv=()=>{const rows=gMembers().map(c=>{const m=gm(c.id),pl=gPlanOf(m);return[gCode(c),gName(c),c.dni||'',c.wa||'',pl?pl.name:'',m.due,gStatus(c).t,GGOALS[m.goal]||'',GLEVELS[m.level]||'',gMonthAtt(c.id),m.decl?'sí':'no'];});
 download(GW().ss+'-'+gT()+'.csv',toCSV(['Código',GW().S,'Documento','WhatsApp',GW().M,'Paga hasta','Estado','Objetivo','Nivel','Asistencias del mes','Declaración de salud'],rows),'text/csv');audit('EXPORTAR',GW().ss+' (CSV)');};
function gCampaignCard(){const sg=gSegments();const K=[['venc','Vencen en los próximos días',sg.venc],['vencida','Cuotas vencidas',sg.vencida],['riesgo','Riesgo de abandono',sg.riesgo],['cumple','Cumplen años hoy',sg.cumple]];
 return`<div class="card" style="margin-top:1rem"><h3>Avisos por WhatsApp</h3><p class="sm mut">Envío asistido uno por uno: el mensaje se abre listo en WhatsApp y lo manda una persona. Sólo ${GW().ss} con consentimiento de comunicaciones.</p><div class="grid g4">${K.map(([k,l,L])=>`<div class="card kpi"><span>${l}</span><b>${L.length}</b><button class="btn sm" data-act="gQueue" data-k="${k}" ${L.length?'':'disabled'}>Preparar envíos</button></div>`).join('')}</div></div>`;}
A.gQueue=el=>{const k=el.dataset.k,L=gSegments()[k==='venc'?'venc':k==='vencida'?'vencida':k==='riesgo'?'riesgo':'cumple'];const ok=L.filter(c=>c.consent&&c.consent.comm!==false&&waDigits(c));
 modal('Avisos por WhatsApp',`<p class="sm mut">${ok.length} listo(s)${L.length-ok.length?' · '+(L.length-ok.length)+' sin consentimiento o sin teléfono':''}. Tocá cada uno: se abre WhatsApp con el texto.</p><div class="tw"><table><tbody>${ok.slice(0,60).map(c=>`<tr><td>${esc(gName(c))}<div class="sm mut">${esc(gStatus(c).t)}</div></td><td class="r">${gWaBtn(c,k,'WhatsApp','gold')}</td></tr>`).join('')||'<tr><td class="mut">Nadie para avisar.</td></tr>'}</tbody></table></div>`,{ok:false,cancelText:'Cerrar',wide:true});};

