function gEdit(c){const m=c?gm(c.id):null;const P=G().plans,trs=S.employees.filter(e=>e.active);
 modal(c?'Editar '+GW().s:'Nuevo '+GW().s,`<div class="grid g2"><div><label for="ge-n">Nombre</label><input id="ge-n" maxlength="40" value="${esc(c?c.name:'')}"></div><div><label for="ge-l">Apellido</label><input id="ge-l" maxlength="40" value="${esc(c?c.last:'')}"></div>
 <div><label for="ge-d">Documento</label><input id="ge-d" inputmode="numeric" value="${esc(c?c.dni:'')}" placeholder="Sin puntos"></div><div><label for="ge-w">WhatsApp</label><input id="ge-w" inputmode="tel" value="${esc(c?String(c.wa||'').replace(/^\+549/,''):'')}" placeholder="Ej: 3875551234"></div>
 <div><label for="ge-b">Fecha de nacimiento</label><input id="ge-b" type="date" value="${esc(c?c.birth:'')}"></div><div><label for="ge-p">${GW().M}</label><select id="ge-p">${P.map(p=>`<option value="${p.id}" ${m&&m.plan===p.id?'selected':''}>${esc(p.name)} · ${money(gPrice(p))}</option>`).join('')}</select></div>
 <div><label for="ge-g">Objetivo</label><select id="ge-g">${Object.entries(GGOALS).map(([k,l])=>`<option value="${k}" ${m&&m.goal===k?'selected':''}>${l}</option>`).join('')}</select></div><div><label for="ge-v">Nivel</label><select id="ge-v">${Object.entries(GLEVELS).map(([k,l])=>`<option value="${k}" ${m&&m.level===k?'selected':''}>${l}</option>`).join('')}</select></div>
 ${isNC()?`<div><label for="ge-mo">Modalidad</label><select id="ge-mo"><option value="presencial">Presencial</option><option value="virtual" ${m&&m.mode==='virtual'?'selected':''}>Programación virtual</option></select></div>`:`<div><label for="ge-nfc">Código de tarjeta NFC</label><input id="ge-nfc" value="${esc(m?m.nfc:'')}" placeholder="Opcional"></div>`}
 <div><label for="ge-t">Profesor a cargo</label><select id="ge-t"><option value="">Sin asignar</option>${trs.map(e=>`<option value="${e.id}" ${m&&m.trainer===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></div></div>
 <fieldset style="border:0;padding:0;margin:.6rem 0 0"><legend class="sm mut">Lesiones a cuidar (el entrenador inteligente las respeta)</legend><div class="row">${Object.entries(GINJ).map(([k,l])=>`<label class="chk"><input type="checkbox" class="ge-i" value="${k}" ${m&&(m.inj||[]).includes(k)?'checked':''}> ${l}</label>`).join('')}</div></fieldset>
 <label for="ge-h">Salud y observaciones</label><textarea id="ge-h" maxlength="300">${esc(m?m.health:'')}</textarea>
 <label class="chk"><input type="checkbox" id="ge-dc" ${m&&m.decl?'checked':''}> Entregó la declaración de salud (apto físico)</label><label class="chk"><input type="checkbox" id="ge-cm" ${!c||!c.consent||c.consent.comm!==false?'checked':''}> Acepta recibir avisos por WhatsApp</label>
 ${c?'':`<p class="sm mut">Queda «Pendiente de primer pago»: al cobrar la primera cuota en Vender se activa.</p>`}`,
 {wide:true,okText:'Guardar',onOk:w=>{const n=val('ge-n').trim(),l=val('ge-l').trim(),d=normDni(val('ge-d')),wa=normWA(val('ge-w'));if(n.length<2)return w._err('Falta el nombre.'),false;
  if(d&&!dniOk(d))return w._err('El documento debe tener 7 u 8 números.'),false;if(d&&S.customers.some(x=>x.dni===d&&(!c||x.id!==c.id)))return w._err('Ya hay un cliente con ese documento.'),false;
  const inj=$$('.ge-i',w).filter(x=>x.checked).map(x=>x.value);const comm=$('#ge-cm',w).checked;let cc=c;
  if(!cc){cc=custCreate({name:n,last:l,birth:val('ge-b'),wa,dni:d,club:true,comm},'mostrador');}else{cc.name=n;cc.last=l;cc.birth=val('ge-b')||'';if(wa)cc.wa=waFull(wa);if(d)cc.dni=d;cc.consent=Object.assign({},cc.consent||{},{comm});}
  const t=gT();let mm=gm(cc.id);const was=mm?mm.plan:'';if(!mm)mm=G().m[cc.id]={due:addDays(t,-1),nuevo:true,measures:[],created:t,freeze:null};
  Object.assign(mm,{plan:val('ge-p'),goal:val('ge-g'),level:val('ge-v'),trainer:val('ge-t'),inj,health:val('ge-h').trim(),decl:$('#ge-dc',w).checked,mode:isNC()?val('ge-mo'):(mm.mode||'presencial'),nfc:isNC()?(mm.nfc||''):val('ge-nfc').trim().toUpperCase()});
  audit(c?(was!==mm.plan?'GYM_CAMBIO_PLAN':'GYM_FICHA'):'GYM_ALTA',gName(cc)+' · '+(gPlanOf(mm)||{}).name);save();rerender();setTimeout(()=>gFichaOpen(cc.id),40);
  toast(c?'Datos guardados':GW().S+' agregado. Cobrá la primera cuota y enviale su app.');}});}

