/* V27.5 · Configuración: grupo propio del gimnasio, primero, con guardado automático y accesos directos */
function gCfgCard(){const C=G().cfg;const L=(isNC()?[['gplanes','Planes y precios','Sesiones por semana, presencial o virtual'],['gagenda','Agenda','Horarios fijos de cada alumno'],['grutinas','Programas','Plantillas y ejercicios'],['gmaq','Equipamiento','Estado y videos']]:[['gplanes','Membresías y precios','Pase libre, clases y pases diarios'],['gclases','Clases','Grilla semanal y cupos'],['grutinas','Rutinas','Plantillas y ejercicios'],['gmaq','Máquinas','Mantenimiento y videos']]).concat([['caja','Caja','Apertura, cierre y arqueo'],['rrhh','Personal','Turnos, fichaje y sueldos'],['fidel','Club y fidelización','Sellos, premios y cumpleaños']]).filter(x=>SCREENS[x[0]]&&(typeof scrOk!=='function'||scrOk(x[0])));
 return`<div class="card" id="gcfg"><h2>${isNC()?'Entrenamiento':'Gimnasio'}: reglas, cobros y accesos</h2><p class="sm mut">Los cambios se guardan solos al salir de cada campo. <b id="gc-msg" aria-live="polite"></b></p>
 <div class="grid g3"><div><label for="gc-g">Período de gracia (días)</label><input id="gc-g" type="number" min="0" max="15" inputmode="numeric" value="${C.grace}"><div class="sm mut">Días extra para entrar con la cuota vencida.</div></div><div><label for="gc-a">Avisar vencimientos con (días)</label><input id="gc-a" type="number" min="1" max="30" inputmode="numeric" value="${C.alertDays}"><div class="sm mut">Aparecen en Avisos y en la ficha.</div></div><div><label for="gc-c">Aforo (personas)</label><input id="gc-c" type="number" min="0" inputmode="numeric" value="${C.capacity}"><div class="sm mut">0 = sin límite.</div></div></div>
 <div class="grid g3"><div><label for="gc-mp">Link de pago fijo (Mercado Pago o Stripe)</label><input id="gc-mp" value="${esc(C.mpLink)}" placeholder="https://link.mercadopago.com.ar/…"></div><div><label for="gc-al">Alias para transferencias</label><input id="gc-al" value="${esc(C.alias)}" placeholder="mi.gimnasio.mp"></div><div><label for="gc-ap">Dirección de la app del ${GW().s}</label><input id="gc-ap" value="${esc(C.appUrl)}" placeholder="${esc(gAppBase())}"></div></div>
 <h3 style="margin-top:1rem">Ir directo a</h3><div class="grid g4">${L.map(x=>`<button type="button" class="btn" style="flex-direction:column;align-items:flex-start;text-align:left;min-height:64px;gap:2px;white-space:normal" data-act="nav" data-id="${x[0]}"><b>${esc(x[1])}</b><span class="sm mut">${esc(x[2])}</span></button>`).join('')}</div></div>`;}
document.addEventListener('change',e=>{const t=e.target;if(t&&t.id&&/^gc-/.test(t.id)&&t.closest('#gcfg'))A.gCfgSave(true);});
A.gPlanEd=el=>{if(!can('gym_admin'))return;const p=el.dataset.id?gPlan(el.dataset.id):null;const pr=p?prod(p.pid):null;
 modal(p?'Editar '+GW().m:(isNC()?'Nuevo plan':'Nueva membresía'),`<label for="gp-n">Nombre</label><input id="gp-n" maxlength="40" value="${esc(p?p.name:'')}"><div class="grid g2"><div><label for="gp-p">Precio ($)</label>${numIn('gp-p',pr?pr.price:0)}</div><div><label for="gp-w">Sesiones por semana (0 = libre)</label><input id="gp-w" inputmode="numeric" value="${p?p.weekly:0}"></div><div><label for="gp-d">Duración</label><select id="gp-d"><option value="0">1 mes</option><option value="1" ${p&&p.days===1?'selected':''}>1 día (pase diario)</option><option value="7" ${p&&p.days===7?'selected':''}>1 semana</option></select></div>${isNC()?`<div><label for="gp-mo">Modalidad</label><select id="gp-mo"><option value="presencial">Presencial</option><option value="virtual" ${p&&p.mode==='virtual'?'selected':''}>Virtual</option></select></div>`:''}</div><label for="gp-x">Descripción (se ve en el menú público)</label><input id="gp-x" maxlength="90" value="${esc(p?p.desc:'')}">`,
 {onOk:w=>{const n=val('gp-n').trim(),price=cents(val('gp-p')),wk=parseInt(val('gp-w'))||0;if(n.length<3)return w._err('Falta el nombre.'),false;if(!(price>0))return w._err('El precio debe ser mayor a cero.'),false;if(wk<0||wk>7)return w._err('Sesiones por semana: de 0 a 7.'),false;
  const days=+val('gp-d')||0,desc=val('gp-x').trim(),mode=isNC()?val('gp-mo'):'presencial';const cat=S.rubros.find(r=>r.id==='gm-memb')?'gm-memb':S.rubros[0].id;
  if(p){const q=prod(p.pid);if(q){if(q.price!==price)audit('PRECIO',q.name+' '+money(q.price)+' → '+money(price),{ent:'producto',eid:q.id,old:q.price,nw:price});q.price=price;q.name=n;q.desc=desc;}Object.assign(p,{name:n,weekly:wk,days,desc,mode});}
  else{const id='gp'+uid();S.products.push({id:'p-'+id,name:n,sub:GW().m,grupo:'',rubro:cat,price,cost:0,stock:9999,unit:'u',barcode:'',plu:'',menu:true,active:true,desc,featured:false,noStock:true,gymPlan:id});G().plans.push({id,pid:'p-'+id,name:n,weekly:wk,days,desc,mode});audit('GYM_PLAN_ALTA',n+' · '+money(price));}
  save();if(typeof pubRefresh==='function')pubRefresh();rerender();}});};

