/* ---------- lockers ---------- */
const LSZ={S:['Chico',4000],M:['Mediano',6000],L:['Grande',8000],XL:['VIP / extra grande',12000]};
const lockNum=id=>{const l=P().lockers.find(x=>x.id===id);return l?l.num:'?';};
const lockerOf=cid=>P().lasg.find(a=>a.cust===cid&&a.active);
function lkState(l){if(l.state==='mant')return['mant','En mantenimiento'];const a=P().lasg.find(x=>x.lk===l.id&&x.active);if(!a)return['libre','Libre'];const d=days(gT(),a.to);if(d<0)return['venc','Vencido hace '+(-d)+' d'];if(d<=5)return['pronto','Vence en '+d+' d'];return['ocup','Hasta '+dmy(a.to)];}
reg('glockers','Lockers y casilleros','lock','gym',()=>{const p=P(),Z=[...new Set(p.lockers.map(l=>l.zone))],z=window.gLkZ||'';const L=p.lockers.filter(l=>!z||l.zone===z);
 const cnt=k=>p.lockers.filter(l=>lkState(l)[0]===k).length,inc=p.lasg.filter(a=>a.active).reduce((s,a)=>s+(+a.rate||0),0);
 return`<div class="row"><h1 class="sp">Lockers y casilleros</h1>${can('gym_admin')?'<button class="btn sm" data-act="gLkNew">Agregar locker</button>':''}</div>
 <div class="grid g4" style="margin-bottom:1rem">${[['Libres',cnt('libre'),'ok'],['Ocupados',cnt('ocup')+cnt('pronto'),''],['Vencen en 5 días',cnt('pronto'),'warn'],['Vencidos',cnt('venc'),'bad']].map(x=>`<div class="card" style="margin:0"><div class="sm mut">${x[0]}</div><b style="font-size:1.6rem">${x[1]}</b></div>`).join('')}</div>
 <div class="card"><div class="row" style="flex-wrap:wrap;gap:.4rem"><b class="sp">Ingreso mensual por lockers: ${money0(inc*100)}</b>${['',...Z].map(x=>`<button class="btn sm ${z===x?'gold':''}" data-act="gLkZ" data-z="${esc(x)}">${esc(x||'Todas las zonas')}</button>`).join('')}</div>
 <div class="gp-lks">${L.map(l=>{const s=lkState(l),a=p.lasg.find(x=>x.lk===l.id&&x.active),c=a&&gCust(a.cust);return`<button type="button" class="gp-lk ${s[0]}" data-act="gLk" data-id="${l.id}" aria-label="Locker ${esc(l.num)}: ${esc(s[1])}"><b>${esc(l.num)}</b><span class="sz">${l.size}</span><span class="who">${c?esc(c.name||gName(c)):esc(s[1])}</span>${c?`<span class="sm">${esc(s[1])}</span>`:''}</button>`;}).join('')}</div>
 <p class="sm mut">Verde libre · gris ocupado · amarillo vence en 5 días o menos · rojo vencido. El cobro se hace en Vender y extiende el alquiler solo. Los avisos de 5 y 2 días aparecen en el Panel de negocio para mandarlos por WhatsApp.</p></div>
 <div class="card"><h3>Apertura con cerradura electrónica (opcional)</h3><p class="sm">Cada locker puede abrirse con el QR dinámico de la app, NFC o una clave de 4 dígitos, con una placa ESP32 con relé en la red del gimnasio. <b>Demostración:</b> en esta demo no hay cerradura conectada, así que el botón "Abrir" sólo registra la orden y no la da por hecha.</p>
 <label for="gp-dev">Dirección de la placa en la red local (ej. http://192.168.0.50)</label><input id="gp-dev" value="${esc(p.cfg.lockDev||'')}" placeholder="Sin placa conectada" ${can('gym_admin')?'':'disabled'}></div>`;},null,'Gimnasio');
A.gLkZ=el=>{window.gLkZ=el.dataset.z;rerender();};
document.addEventListener('change',e=>{if(e.target&&e.target.id==='gp-dev'){const v=e.target.value.trim();if(v&&!/^https?:\/\/[\w.-]+(:\d+)?\/?$/i.test(v))return toast('Escribí una dirección como http://192.168.0.50',1);P().cfg.lockDev=v;save();toast('Guardado');}});
A.gLk=el=>{const p=P(),l=p.lockers.find(x=>x.id===el.dataset.id);if(!l)return;const a=p.lasg.find(x=>x.lk===l.id&&x.active),c=a&&gCust(a.cust),s=lkState(l);
 if(!a){modal('Locker '+l.num+' · '+LSZ[l.size][0],`<p class="sm">${esc(l.zone)} · ${l.state==='mant'?'<b>en mantenimiento</b>':'libre'}</p>${l.state==='mant'?'':`<label for="lk-c">Asignar a</label>${custSel('lk-c')}<div class="grid g3"><div><label for="lk-f">Desde</label><input id="lk-f" type="date" value="${gT()}"></div><div><label for="lk-m">Meses</label><input id="lk-m" type="number" min="1" max="12" value="1"></div><div><label for="lk-r">Tarifa mensual ($)</label><input id="lk-r" type="number" min="0" value="${l.rate||LSZ[l.size][1]}"></div></div><label for="lk-k">Clave de 4 dígitos (opcional)</label><input id="lk-k" inputmode="numeric" maxlength="4" placeholder="Ej. 4821">`}
  ${can('gym_admin')?`<p style="margin-top:.8rem" class="row"><button class="btn sm" data-act="gLkMant" data-id="${l.id}">${l.state==='mant'?'Volver a habilitar':'Pasar a mantenimiento'}</button><button class="btn sm" data-act="gLkEd" data-id="${l.id}">Editar locker</button><button class="btn sm" data-act="gLkDel" data-id="${l.id}">Borrar locker</button></p>`:''}`,
  l.state==='mant'?{ok:false,cancelText:'Cerrar'}:{okText:'Asignar y cobrar en Vender',onOk:w=>{const cu=gCust(val('lk-c')),f=val('lk-f')||gT(),mm=Math.max(1,Math.min(12,parseInt(val('lk-m'))||1)),r=Math.max(0,parseInt(val('lk-r'))||0),k=val('lk-k').trim();
   if(!cu)return w._err('Elegí '+(isNC()?'el alumno':'el socio')+'.'),false;if(k&&!/^\d{4}$/.test(k))return w._err('La clave tiene que tener 4 números.'),false;if(lockerOf(cu.id))return w._err('Ya tiene el locker '+lockNum(lockerOf(cu.id).lk)+'.'),false;
   p.lasg.push({id:uid(),lk:l.id,cust:cu.id,from:f,to:addDays(f,-1),rate:r,pin:k,active:true,created:now()});audit('GYM_LOCKER_ASIGNADO','Locker '+l.num+' · '+gName(cu));save();ensureProd('p-locker','Alquiler de locker (mes)',r*100);toPos(cu,'p-locker',r*100,mm,'Alquiler de locker '+l.num+' (mes)');}});return;}
 modal('Locker '+l.num+' · '+esc(gName(c)),`<p>${esc(l.zone)} · ${LSZ[l.size][0]} · <b>${esc(s[1])}</b> · tarifa ${money0((a.rate||0)*100)} por mes${a.pin?' · tiene clave':''}</p>
 <div class="row" style="flex-wrap:wrap;gap:.4rem"><button class="btn gold" data-act="gLkPay" data-id="${a.id}">Cobrar 1 mes en Vender</button>${gpWa(c,lkMsg(c,a),'Recordar por WhatsApp','locker')}<button class="btn" data-act="gLkOpen" data-id="${l.id}">Abrir (demostración)</button><button class="btn" data-act="gLkFree" data-id="${a.id}">Liberar locker</button><button class="btn" data-act="gLkAsgEd" data-id="${a.id}">Editar alquiler</button>${can('gym_admin')?`<button class="btn" data-act="gLkEd" data-id="${l.id}">Editar locker</button>`:''}</div>`,{ok:false,cancelText:'Cerrar'});};
function lkMsg(c,a){const d=days(gT(),a.to),biz=S.tenant.name,C=G().cfg;return`Hola ${c.name||''}, tu locker ${lockNum(a.lk)} en ${biz} ${d<0?'venció el '+dmy(a.to):d===0?'vence hoy':'vence el '+dmy(a.to)}. Renovalo en recepción${C.alias?' o por transferencia al alias '+C.alias:''} para conservarlo.`;}
A.gLkPay=el=>{const a=P().lasg.find(x=>x.id===el.dataset.id);if(!a)return;ensureProd('p-locker','Alquiler de locker (mes)',(a.rate||0)*100);toPos(gCust(a.cust),'p-locker',(a.rate||0)*100,1,'Alquiler de locker '+lockNum(a.lk)+' (mes)');};
A.gLkOpen=el=>{const l=P().lockers.find(x=>x.id===el.dataset.id);if(!l)return;audit('GYM_LOCKER_APERTURA','Orden de apertura locker '+l.num+' (demostración, sin cerradura conectada)');save();toast(P().cfg.lockDev?'Orden registrada. En la instalación real la placa abre la cerradura y confirma.':'Demostración: no hay cerradura conectada, la orden quedó registrada y el locker no se abrió.');};
A.gLkFree=el=>{const a=P().lasg.find(x=>x.id===el.dataset.id);if(!a)return;confirmBox('Liberar locker','El locker '+esc(lockNum(a.lk))+' queda libre.',()=>{a.active=false;a.end=gT();audit('GYM_LOCKER_LIBERADO','Locker '+lockNum(a.lk)+' · '+gName(gCust(a.cust)));save();$$('#modal-root .ov').forEach(o=>o.remove());rerender();});};
A.gLkMant=el=>{const l=P().lockers.find(x=>x.id===el.dataset.id);if(!l)return;l.state=l.state==='mant'?'ok':'mant';save();$$('#modal-root .ov').forEach(o=>o.remove());rerender();};
A.gLkEd=el=>{const l=P().lockers.find(x=>x.id===el.dataset.id);if(!l)return;$$('#modal-root .ov').forEach(o=>o.remove());modal('Editar locker '+l.num,`<div class="grid g4"><div><label for="le-n">Número</label><input id="le-n" maxlength="6" value="${esc(l.num)}"></div><div><label for="le-s">Tamaño</label><select id="le-s">${Object.keys(LSZ).map(k=>`<option value="${k}"${l.size===k?' selected':''}>${k} · ${LSZ[k][0]}</option>`).join('')}</select></div><div><label for="le-z">Zona</label><input id="le-z" maxlength="30" value="${esc(l.zone)}"></div><div><label for="le-r">Tarifa mensual ($)</label><input id="le-r" type="number" min="0" value="${l.rate||LSZ[l.size][1]}"></div></div>`,
 {okText:'Guardar',onOk:w=>{const n=val('le-n').trim();if(!n)return w._err('Escribí el número.'),false;if(P().lockers.some(x=>x.num===n&&x.id!==l.id))return w._err('Ese número ya existe.'),false;Object.assign(l,{num:n,size:val('le-s'),zone:val('le-z').trim()||'General',rate:Math.max(0,parseInt(val('le-r'))||0)});audit('GYM_LOCKER_EDITADO','Locker '+n);save();rerender();}});};
A.gLkDel=el=>{const p=P(),l=p.lockers.find(x=>x.id===el.dataset.id);if(!l)return;const a=p.lasg.find(x=>x.lk===l.id&&x.active);if(a)return toast('Primero liberá el locker (está asignado a '+gName(gCust(a.cust))+').',1);
 confirmBox('Borrar locker '+esc(l.num),'Se quita del mapa. El historial de alquileres queda registrado. Podés deshacerlo enseguida.',()=>{p.lockers=p.lockers.filter(x=>x.id!==l.id);audit('GYM_LOCKER_BORRADO','Locker '+l.num);save();$$('#modal-root .ov').forEach(o=>o.remove());rerender();});};
A.gLkAsgEd=el=>{const a=P().lasg.find(x=>x.id===el.dataset.id);if(!a)return;$$('#modal-root .ov').forEach(o=>o.remove());modal('Editar alquiler · locker '+lockNum(a.lk),`<p class="sm">${esc(gName(gCust(a.cust)))}</p><div class="grid g3"><div><label for="la-t">Pagado hasta</label><input id="la-t" type="date" value="${a.to}"></div><div><label for="la-r">Tarifa mensual ($)</label><input id="la-r" type="number" min="0" value="${a.rate||0}"></div><div><label for="la-k">Clave (4 dígitos)</label><input id="la-k" inputmode="numeric" maxlength="4" value="${esc(a.pin||'')}"></div></div>`,
 {okText:'Guardar',onOk:w=>{const t=val('la-t'),k=val('la-k').trim();if(!/^\d{4}-\d{2}-\d{2}$/.test(t))return w._err('Elegí la fecha.'),false;if(k&&!/^\d{4}$/.test(k))return w._err('La clave tiene que tener 4 números.'),false;const prev=a.to;Object.assign(a,{to:t,rate:Math.max(0,parseInt(val('la-r'))||0),pin:k});audit('GYM_LOCKER_ALQUILER_EDITADO','Locker '+lockNum(a.lk)+' · '+dmy(prev)+' → '+dmy(t));save();rerender();}});};
