reg('gcred','Packs y créditos de clases','check','gym',()=>{const L=gActives().map(c=>[c,credOf(gm(c.id))]).filter(x=>x[1]!=null).sort((a,b)=>a[1]-b[1]);const packs=G().plans.filter(p=>credPack(p));
 return`<div class="row"><h1 class="sp">Packs y créditos de clases</h1></div><p class="mut">Ideal para danza, pilates, yoga, academias y boxes: cada pack trae créditos, cada clase con presente descuenta uno y la cancelación tardía también. Sin créditos libres no se puede reservar.</p>
 <div class="card"><h3>Packs a la venta</h3>${packs.length?packs.map(p=>`<span class="tag ok" style="margin:.2rem">${esc(p.name)} · ${credPack(p)} créditos · ${money0(gPrice(p))}</span>`).join(''):'<p class="sm mut">Creá un plan con "Pack" y la cantidad en el nombre (ej. "Pack 8 clases").</p>'}</div>
 <div class="card"><h3>Saldo de cada ${GW().s}</h3><div class="tw"><table><thead><tr><th>${GW().S}</th><th>Pack</th><th>Créditos</th><th></th></tr></thead><tbody>${L.map(([c,cr])=>`<tr><td>${esc(gName(c))}</td><td>${esc((gPlanOf(gm(c.id))||{}).name||'')}</td><td>${cr<=0?'<span class="tag bad">Sin créditos</span>':cr<=1?`<span class="tag warn">${cr}</span>`:`<b>${cr}</b>`}</td><td class="r"><button class="btn sm" data-act="gCrAdj" data-id="${c.id}" data-d="1">+1</button><button class="btn sm" data-act="gCrAdj" data-id="${c.id}" data-d="-1">−1</button><button class="btn sm gold" data-act="gPay" data-id="${c.id}">Renovar pack</button>${cr<=1?gpWa(c,`Hola ${c.name||''}, ${cr<=0?'se terminaron los créditos de tu pack':'te queda 1 crédito en tu pack'} en ${S.tenant.name}. ¿Te reservo uno nuevo?`,'Avisar','pack'):''}</td></tr>`).join('')||'<tr><td colspan="4" class="mut">Nadie tiene packs con créditos.</td></tr>'}</tbody></table></div></div>`;},null,'Gimnasio');
A.gCrAdj=el=>{if(!can('gym_admin'))return toast('Sólo un administrador ajusta créditos.',1);const c=gCust(el.dataset.id),m=gm(el.dataset.id);if(!m)return;const cr=credOf(m);m.cred=Math.max(0,(cr||0)+(+el.dataset.d));audit('GYM_CREDITOS_AJUSTE',gName(c)+' · '+(+el.dataset.d>0?'+':'')+el.dataset.d+' · saldo '+m.cred);save();rerender();};

