/* ---------- torneos: fixture automático y tabla de posiciones ---------- */
function fixture(teams){const T=teams.slice();if(T.length%2)T.push(null);const n=T.length,R=[];for(let r=0;r<n-1;r++){const M=[];for(let i=0;i<n/2;i++){const a=T[i],b=T[n-1-i];if(a&&b)M.push(r%2?[b,a]:[a,b]);}R.push(M);T.splice(1,0,T.pop());}return R;}
function table(t){const S0={};t.teams.forEach(x=>S0[x]={eq:x,pj:0,pg:0,pe:0,pp:0,gf:0,gc:0,adj:0});t.rounds.forEach(R=>R.forEach(m=>{if(m.a==null||m.b==null||m.ga===''||m.gb==='')return;const A0=S0[m.h],B=S0[m.v];if(!A0||!B)return;const a=+m.ga,b=+m.gb;A0.pj++;B.pj++;A0.gf+=a;A0.gc+=b;B.gf+=b;B.gc+=a;if(a>b){A0.pg++;B.pp++;}else if(a<b){B.pg++;A0.pp++;}else{A0.pe++;B.pe++;}}));
 Object.keys(t.adj||{}).forEach(k=>{if(S0[k])S0[k].adj=+t.adj[k]||0;});return Object.values(S0).map(x=>Object.assign(x,{dg:x.gf-x.gc,pts:x.pg*3+x.pe+x.adj})).sort((a,b)=>b.pts-a.pts||b.dg-a.dg||b.gf-a.gf||a.eq.localeCompare(b.eq,'es'));}
reg('gtorneos','Torneos y posiciones','list','gym',()=>{const p=P(),t=p.tourn.find(x=>x.id===window.gTo)||p.tourn[0];
 return`<div class="row"><h1 class="sp">Torneos y posiciones</h1>${p.tourn.map(x=>`<button class="btn sm ${t&&x.id===t.id?'gold':''}" data-act="gToSel" data-id="${x.id}">${esc(x.name)}</button>`).join('')}<button class="btn sm" data-act="gToNew">Nuevo torneo</button>${t?`<button class="btn sm" data-act="gToEd" data-id="${t.id}">Editar</button><button class="btn sm" data-act="gToDel" data-id="${t.id}">Borrar</button>`:''}</div>
 ${t?`<div><div class="card"><h3>Tabla de posiciones · ${esc(t.name)}</h3><div class="tw"><table><thead><tr><th>#</th><th>Equipo</th><th>PJ</th><th>PG</th><th>PE</th><th>PP</th><th>GF</th><th>GC</th><th>DG</th><th>Pts</th><th title="Ajuste de puntos (sanciones o bonificaciones)">Ajuste</th></tr></thead><tbody>${table(t).map((x,i)=>`<tr><td>${i+1}</td><td><b>${esc(x.eq)}</b></td><td>${x.pj}</td><td>${x.pg}</td><td>${x.pe}</td><td>${x.pp}</td><td>${x.gf}</td><td>${x.gc}</td><td>${x.dg>0?'+':''}${x.dg}</td><td><b>${x.pts}</b></td><td><input type="number" class="gp-adj" data-t="${t.id}" data-eq="${esc(x.eq)}" value="${x.adj}" style="width:64px" aria-label="Ajuste de puntos de ${esc(x.eq)}"></td></tr>`).join('')}</tbody></table></div>
  <div class="row" style="margin-top:.6rem"><button class="btn sm" data-act="gToCopy" data-id="${t.id}">Copiar tabla para WhatsApp o redes</button></div></div>
 <div class="card"><h3>Fixture (todos contra todos)</h3><div class="grid g3">${t.rounds.map((R,ri)=>`<div><h4 style="margin:.6rem 0 .2rem">Fecha ${ri+1}</h4>${R.map((m,mi)=>`<div class="row" style="gap:.4rem;margin:.2rem 0"><span class="sp" style="text-align:right">${esc(m.h)}</span><input class="gp-g" data-t="${t.id}" data-r="${ri}" data-m="${mi}" data-s="ga" inputmode="numeric" value="${m.ga}" style="width:46px;text-align:center" aria-label="Goles de ${esc(m.h)}"><span>-</span><input class="gp-g" data-t="${t.id}" data-r="${ri}" data-m="${mi}" data-s="gb" inputmode="numeric" value="${m.gb}" style="width:46px;text-align:center" aria-label="Goles de ${esc(m.v)}"><span class="sp">${esc(m.v)}</span></div>`).join('')}</div>`).join('')}</div></div></div>`:'<div class="card"><p>Creá el primer torneo: escribí los equipos y el fixture se arma solo.</p></div>'}`;},null,'Gimnasio');
A.gToEd=el=>{const t=P().tourn.find(z=>z.id===el.dataset.id);if(!t)return;modal('Editar torneo',`<label for="te-n">Nombre</label><input id="te-n" maxlength="40" value="${esc(t.name)}"><label for="te-e">Equipos (uno por renglón)</label><textarea id="te-e" rows="8">${esc(t.teams.join('\n'))}</textarea><p class="sm mut">Si cambiás el nombre de un equipo en el mismo renglón, se renombra en todo el fixture. Si agregás o quitás equipos, el fixture se vuelve a armar y se conservan los resultados de los partidos que siguen existiendo.</p>`,
 {okText:'Guardar',onOk:w=>{const n=val('te-n').trim(),E=val('te-e').split('\n').map(x=>x.trim()).filter(Boolean);if(!n)return w._err('Escribí el nombre.'),false;if(E.length<3)return w._err('Hacen falta al menos 3 equipos.'),false;if(new Set(E).size!==E.length)return w._err('Hay equipos repetidos.'),false;
  if(E.length===t.teams.length){const map={};t.teams.forEach((x,i)=>map[x]=E[i]);t.rounds.forEach(R0=>R0.forEach(m=>{m.h=map[m.h];m.v=map[m.v];}));const adj={};Object.keys(t.adj||{}).forEach(k=>{if(map[k])adj[map[k]]=t.adj[k];});t.adj=adj;}
  else{const old={};t.rounds.forEach(R0=>R0.forEach(m=>{old[m.h+'|'+m.v]=m;}));t.rounds=fixture(E).map(R0=>R0.map(([h,v])=>{const o=old[h+'|'+v]||old[v+'|'+h];return o&&o.h===h?{h,v,a:1,b:1,ga:o.ga,gb:o.gb}:o?{h,v,a:1,b:1,ga:o.gb,gb:o.ga}:{h,v,a:1,b:1,ga:'',gb:''};}));}
  t.teams=E;t.name=n;audit('GYM_TORNEO_EDITADO',n);save();rerender();}});};
A.gToDel=el=>{const p=P(),t=p.tourn.find(z=>z.id===el.dataset.id);if(!t)return;confirmBox('Borrar '+esc(t.name),'Se borran el fixture y la tabla. Podés deshacerlo enseguida.',()=>{p.tourn=p.tourn.filter(z=>z.id!==t.id);window.gTo='';audit('GYM_TORNEO_BORRADO',t.name);save();rerender();});};
A.gToSel=el=>{window.gTo=el.dataset.id;rerender();};
A.gToNew=()=>modal('Nuevo torneo',`<label for="to-n">Nombre</label><input id="to-n" maxlength="40" placeholder="Torneo Apertura de Fútbol 5"><label for="to-e">Equipos (uno por renglón)</label><textarea id="to-e" rows="8" placeholder="Los Pibes&#10;La Banda&#10;..."></textarea>`,{okText:'Armar fixture',onOk:w=>{const n=val('to-n').trim(),E=[...new Set(val('to-e').split('\n').map(x=>x.trim()).filter(Boolean))];if(!n)return w._err('Escribí el nombre.'),false;if(E.length<3)return w._err('Hacen falta al menos 3 equipos.'),false;if(E.length>24)return w._err('Máximo 24 equipos.'),false;
 const t={id:uid(),name:n,teams:E,rounds:fixture(E).map(R=>R.map(([h,v])=>({h,v,a:1,b:1,ga:'',gb:''}))),adj:{},created:now()};P().tourn.push(t);window.gTo=t.id;audit('GYM_TORNEO',n+' · '+E.length+' equipos');save();rerender();}});
document.addEventListener('change',e=>{const x=e.target;if(!x||!x.classList)return;
 if(x.classList.contains('gp-g')){const t=P().tourn.find(z=>z.id===x.dataset.t);if(!t)return;const v=x.value.trim();if(v!==''&&!/^\d{1,2}$/.test(v))return toast('Poné un número de goles.',1);t.rounds[+x.dataset.r][+x.dataset.m][x.dataset.s]=v;save();rerender();}
 if(x.classList.contains('gp-adj')){const t=P().tourn.find(z=>z.id===x.dataset.t);if(!t)return;t.adj=t.adj||{};t.adj[x.dataset.eq]=parseInt(x.value)||0;audit('GYM_TORNEO_AJUSTE',t.name+' · '+x.dataset.eq+' '+t.adj[x.dataset.eq]);save();rerender();}});
A.gToCopy=async el=>{const t=P().tourn.find(z=>z.id===el.dataset.id);if(!t)return;const txt='*'+t.name+'* · '+S.tenant.name+'\n'+table(t).map((x,i)=>(i+1)+'. '+x.eq+' — '+x.pts+' pts ('+x.pj+' PJ, DG '+(x.dg>0?'+':'')+x.dg+')').join('\n');try{await navigator.clipboard.writeText(txt);toast('Tabla copiada');}catch(e){modal('Tabla',`<textarea rows="10" readonly>${esc(txt)}</textarea>`,{ok:false,cancelText:'Cerrar'});}};

/* ---------- deportes de contacto: categorías de peso, nivel y sparring ---------- */
const WCAT=[[52,'Mosca'],[57,'Gallo'],[61,'Pluma'],[66,'Ligero'],[70,'Superligero'],[77,'Welter'],[84,'Mediano'],[93,'Semipesado'],[999,'Pesado']];
const wcat=kg=>{kg=+kg;if(!kg)return'';return(WCAT.find(x=>kg<=x[0])||WCAT[WCAT.length-1])[1];};
const LV=['Inicial','Intermedio','Avanzado','Competidor'];
const kgOf=m=>{if(!m)return 0;if(m.kg)return+m.kg;const L=(m.measures||[]).filter(x=>x.peso).sort((a,b)=>a.date.localeCompare(b.date));return L.length?+L[L.length-1].peso:0;};
reg('gcontacto','Categorías y sparring','users','gym',()=>{const A0=gActives(),by={};A0.forEach(c=>{const m=gm(c.id),k=wcat(kgOf(m))||'Sin pesar';(by[k]=by[k]||[]).push(c);});const pr=window.gSpar||[];
 return`<div class="row"><h1 class="sp">Categorías y sparring</h1><button class="btn gold" data-act="gSpGen">Armar parejas de sparring de hoy</button></div><p class="mut">Categoría por peso (tomado de la ficha o de la última medición) y nivel. Las parejas se arman sólo entre los presentes de hoy, misma categoría o la vecina y nivel parecido.</p>
 ${pr.length?`<div class="card"><h3>Parejas de hoy</h3>${pr.map(x=>`<div class="row"><b class="sp">${esc(gName(gCust(x[0])))}</b><span class="tag">${esc(x[2])}</span><b class="sp" style="text-align:right">${x[1]?esc(gName(gCust(x[1]))):'<span class="mut">sin pareja: trabaja con el profe</span>'}</b></div>`).join('')}<p class="row"><button class="btn sm" data-act="gSpSave">Registrar sparring</button><button class="btn sm" data-act="gSpClr">Borrar parejas</button></p></div>`:''}
 <div class="grid g3">${WCAT.map(x=>x[1]).concat('Sin pesar').filter(k=>by[k]).map(k=>`<div class="card"><h3>${esc(k)} <span class="sm mut">${by[k].length}</span></h3>${by[k].map(c=>{const m=gm(c.id);return`<div class="row" style="margin:.25rem 0"><span class="sp">${esc(gName(c))}</span><span class="sm mut">${kgOf(m)?kgOf(m)+' kg':''}</span><select class="gp-lv" data-id="${c.id}" aria-label="Nivel de ${esc(gName(c))}">${LV.map(l=>`<option${(m.lvl||'Inicial')===l?' selected':''}>${l}</option>`).join('')}</select>${gAttToday(c.id)?'<span class="tag ok">hoy</span>':''}</div>`;}).join('')}</div>`).join('')}</div>`;},null,'Gimnasio');
document.addEventListener('change',e=>{const x=e.target;if(x&&x.classList&&x.classList.contains('gp-lv')){const m=gm(x.dataset.id);if(m){m.lvl=x.value;save();}}});
A.gSpGen=()=>{const ord=WCAT.map(x=>x[1]);const L=gActives().filter(c=>gAttToday(c.id)).map(c=>{const m=gm(c.id);return{c,k:ord.indexOf(wcat(kgOf(m))),kg:kgOf(m),l:LV.indexOf(m.lvl||'Inicial')};}).filter(x=>x.k>=0).sort((a,b)=>a.kg-b.kg);
 const used=new Set(),out=[];L.forEach(x=>{if(used.has(x.c.id))return;used.add(x.c.id);let best=null,bs=99;L.forEach(y=>{if(used.has(y.c.id))return;const s=Math.abs(x.k-y.k)*2+Math.abs(x.l-y.l);if(Math.abs(x.k-y.k)<=1&&Math.abs(x.l-y.l)<=1&&s<bs){bs=s;best=y;}});if(best)used.add(best.c.id);out.push([x.c.id,best?best.c.id:'',WCAT[x.k][1]]);});
 window.gSpar=out;if(!out.length)toast('Hoy todavía no hay presentes con peso cargado.',1);rerender();};
A.gSpClr=()=>{window.gSpar=[];rerender();};
A.gSpSave=()=>{const pr=window.gSpar||[];P().spar.push({id:uid(),date:gT(),pairs:pr});audit('GYM_SPARRING',pr.length+' pareja(s)');save();toast('Sparring registrado');};

