/* ---------- panel de negocio ---------- */
function metrics(){const t=gT(),g=+G().cfg.grace||0,A0=gActives(),M=gMembers();
 const paying=A0.filter(c=>{const m=gm(c.id);return m.due>=addDays(t,-g)&&!gFrozen(m);});
 const mrr=paying.reduce((s,c)=>{const pl=gPlanOf(gm(c.id));return s+(pl&&!pl.days?gPrice(pl):0);},0);
 const lost=M.filter(c=>{const m=gm(c.id);return(m.baja&&(m.bajaDate||m.due)>=addDays(t,-30))||(!m.baja&&m.due<addDays(t,-g)&&m.due>=addDays(t,-30-g));});
 const churn=lost.length/Math.max(1,paying.length+lost.length);
 const due30=A0.filter(c=>{const m=gm(c.id);return m.due>=t&&m.due<=addDays(t,30);});const gross=due30.reduce((s,c)=>{const pl=gPlanOf(gm(c.id));return s+(pl?gPrice(pl):0);},0);
 const cls=G().classes;const capW=cls.reduce((s,c)=>s+(+c.cap||0),0);const from=addDays(t,-28);const att=G().catt.filter(a=>a.date>=from&&a.date<t).length;const occ=capW?att/(capW*4):0;
 const next=cls.reduce((s,c)=>s+G().res.filter(r=>r.cid===c.id&&r.date===gNextDate(c.day)).length,0);const occN=capW?next/capW:0;
 const arpu=paying.length?mrr/paying.length:0,ltv=churn>0?arpu/churn:arpu*24;
 return{mrr,churn,lost,paying,gross,exp:gross*(1-churn),due30,occ,occN,arpu,ltv};}
function live(){const t=gT(),A0=G().acc.filter(a=>dkey(a.ts)===t).sort((a,b)=>b.ts-a.ts),ok=A0.filter(a=>a.res!=='denied'),den=A0.length-ok.length,h2=ok.filter(a=>now()-a.ts<2*36e5).length;
 const hm=ts=>new Date(ts).toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'});const ico={ok:'✓',warn:'!',denied:'✕'};
 return`<div class="gp-k" style="grid-column:1/-1"><div class="row" style="flex-wrap:wrap;gap:1.4rem;align-items:flex-start"><div><div class="gp-kt"><span class="gp-live" aria-hidden="true"></span>Accesos en tiempo real</div><b>${ok.length}</b><div class="gp-ks">ingresos hoy · ${h2} en las últimas 2 h${den?' · '+den+' rechazado(s)':''}</div></div>
 <ul class="gp-feed sp" aria-live="polite">${A0.slice(0,6).map(a=>{const c=gCust(a.cust);return`<li><span>${hm(a.ts)}</span><span class="tag ${a.res==='denied'?'bad':a.res==='warn'?'warn':'ok'}">${ico[a.res]||'✓'}</span><b style="font-size:.9rem;margin:0">${esc(c?gName(c):'—')}</b><span class="sm mut">${esc(a.res==='denied'?(a.why||'rechazado'):(a.src==='portero'?'portero':({qr:'QR',nfc:'NFC',dni:'DNI',manual:'recepción'}[a.method]||a.method||'')))}</span></li>`;}).join('')||'<li class="mut">Todavía no hubo ingresos hoy.</li>'}</ul>
 <button class="btn sm" data-act="nav" data-id="gacceso">Control de acceso</button></div></div>`;}
function weeks(n){const t=gT(),ws=gWeekStart(t),out=[];for(let i=n-1;i>=0;i--){const a=addDays(ws,-7*i),b=addDays(a,7);const v=S.sales.filter(s=>s.status==='ok'&&dkey(s.ts)>=a&&dkey(s.ts)<b).reduce((x,s)=>x+(s.total||0),0);out.push([a.slice(8,10)+'/'+a.slice(5,7),v]);}return out;}
