/* ---------- deshacer: cada cambio en las pantallas del gimnasio se puede revertir ---------- */
let snap=null,quiet=false,undoStack=[];
const inG=()=>/^g/.test(curScreen)||curScreen==='config';
const take=e=>{if(quiet||!inG())return;if(e.type==='click'&&!e.target.closest('[data-act],button'))return;try{snap=JSON.stringify(S.gym);}catch(x){snap=null;}};
document.addEventListener('click',take,true);document.addEventListener('change',take,true);
const _save=save;save=function(){const r=_save.apply(this,arguments);try{if(snap&&!quiet){const cur=JSON.stringify(S.gym);if(cur!==snap){undoStack.push({s:snap,t:Date.now(),scr:curScreen});if(undoStack.length>20)undoStack.shift();snap=cur;offer();}}}catch(e){}return r;};
function offer(){const box=$('#toast');if(!box)return;$$('#toast .gp-undo').forEach(x=>x.remove());const d=document.createElement('div');d.className='gp-undo';d.innerHTML='<span>Cambio guardado</span><button type="button">Deshacer</button>';d.querySelector('button').addEventListener('click',()=>{d.remove();undo();});box.appendChild(d);setTimeout(()=>d.remove(),9000);}
function undo(){const u=undoStack.pop();if(!u)return toast('No hay cambios para deshacer.',1);quiet=true;try{S.gym=JSON.parse(u.s);audit('GYM_DESHACER','Se revirtió el último cambio en '+u.scr);_save();}finally{quiet=false;}snap=null;$$('#modal-root .ov').forEach(o=>o.remove());rerender();toast('Cambio deshecho'+(undoStack.length?' · podés seguir deshaciendo':''));}
A.gUndo=undo;
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&!e.shiftKey&&e.key.toLowerCase()==='z'&&inG()&&undoStack.length){const t=e.target;if(t&&/INPUT|TEXTAREA|SELECT/.test(t.tagName))return;e.preventDefault();undo();}});
const _sw=sweep;sweep=function(){quiet=true;try{return _sw.apply(this,arguments);}finally{quiet=false;}};
const _sd=seed;seed=function(){quiet=true;try{return _sd.apply(this,arguments);}finally{quiet=false;}};

