 const draw=()=>{const c=val('ro-c'),L=c?(((X().logs[c]=X().logs[c]||{})[p.id])||(X().logs[c][p.id]={})):{};RXR.render($('#ro-v'),p.plan,{logs:L,video:vidOf,openVideo:it=>{const e=G().ex.find(x=>x.id===it.ejercicio_biblioteca_id);if(e)A.gVideo({dataset:{k:'ex',id:e.id}});},onLog:c?(()=>{save();}):null,onSwap:(bi,ii)=>swapUI(p.plan,bi,ii,()=>A.gRxOpen({dataset:{id:p.id}}))});};
